 M internal/ui/oci_resources/update.go
?? internal/ui/dashboard/focus_test.go
?? internal/ui/oci_resources/focus_routing_test.go
 internal/ui/dashboard/model.go        | 38 +++++++++++++++++++++++++++++++++--
 internal/ui/oci_resources/commands.go |  3 ++-
 internal/ui/oci_resources/model.go    |  5 ++++-
 internal/ui/oci_resources/update.go   | 21 ++++++++++++++++++-
 4 files changed, 62 insertions(+), 5 deletions(-)
diff --git i/internal/ui/dashboard/model.go w/internal/ui/dashboard/model.go
index 9682dd02..2e583939 100644
--- i/internal/ui/dashboard/model.go
+++ w/internal/ui/dashboard/model.go
@@ -62,7 +62,9 @@ type RefreshTickMsg time.Time
 // (GitLab, `system df`, workspaces, tools) ≈ 600 ms plus the network. A single
 // clock for all three would make the cheap call wait behind the expensive
 // one.
-const (
+//
+// They are vars so a test can shorten them (testutil.FastTimers).
+var (
 	hostTickInterval   = time.Second
 	dockerTickInterval = 5 * time.Second
 )
@@ -171,6 +173,10 @@ type Model struct {
 	// Refresh
 	refreshInterval time.Duration

+	// blurred is true while the terminal window has lost the focus
+	// (DEVDESK-210). The three clocks keep their timers but skip the I/O.
+	blurred bool
+
 	// footer is the one line of transient state below the viewport (Rule 128).
 	// The dashboard budgets an info line and left it permanently empty; a key
 	// the header greys out has to be able to say why it declined (Rule 130).
@@ -260,16 +266,28 @@ func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 	case WorkspaceStatsMsg:
 		return m.handleWorkspaceStats(msg)

+	case shared.TerminalFocusMsg:
+		return m.handleTerminalFocus(msg)
+
 	case RefreshTickMsg:
+		if m.blurred {
+			return m, m.scheduleRefresh()
+		}
 		return m.alsoMeasuringSize(m.refreshAll())

 	case HostTickMsg:
+		if m.blurred {
+			return m, m.scheduleHostTick()
+		}
 		return m, tea.Batch(m.sampleHost(), m.scheduleHostTick())

 	case HostSampleMsg:
 		return m.handleHostSample(msg)

 	case DockerTickMsg:
+		if m.blurred {
+			return m, m.scheduleDockerTick()
+		}
 		return m, tea.Batch(m.fetchDockerMetrics(), m.scheduleDockerTick())

 	case DockerMetricsMsg:
@@ -293,6 +311,18 @@ func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 	return m, nil
 }

+// handleTerminalFocus records the focus level. On the edge that follows a blur
+// (Resume) each clock reads once, **without rearming**: the chains kept their
+// timers while blurred, a second one would double the rate. The level alone
+// starts nothing.
+func (m Model) handleTerminalFocus(msg shared.TerminalFocusMsg) (tea.Model, tea.Cmd) {
+	m.blurred = !msg.Focused
+	if !msg.Resume {
+		return m, nil
+	}
+	return m.alsoMeasuringSize(tea.Batch(m.slowRound(), m.sampleHost(), m.fetchDockerMetrics()))
+}
+
 // handleKeyMsg processes keyboard input
 func (m Model) handleKeyMsg(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
 	switch msg.String() {
@@ -638,6 +668,11 @@ func (m Model) scheduleRefresh() tea.Cmd {
 // other two have theirs, and a slow round that restarted them would make two
 // tick chains for the same clock, hence samples twice as fast.
 func (m Model) refreshAll() tea.Cmd {
+	return tea.Batch(m.slowRound(), m.scheduleRefresh())
+}
+
+// slowRound is the slow clock's reads, without its timer.
+func (m Model) slowRound() tea.Cmd {
 	return tea.Batch(
 		m.checkServices(),
 		m.fetchForgeStats(),
@@ -646,7 +681,6 @@ func (m Model) refreshAll() tea.Cmd {
 		m.fetchWorkspaceStats(),
 		m.fetchDiskUsage(),
 		m.fetchPosture(),
-		m.scheduleRefresh(),
 	)
 }

diff --git i/internal/ui/oci_resources/commands.go w/internal/ui/oci_resources/commands.go
index 6eea2991..7aaf3516 100644
--- i/internal/ui/oci_resources/commands.go
+++ w/internal/ui/oci_resources/commands.go
@@ -25,7 +25,8 @@ import (
 	"github.com/anthnel/devdesk/internal/scan"
 )

-const refreshInterval = 10 * time.Second
+// refreshInterval is a var so a test can shorten it (testutil.FastTimers).
+var refreshInterval = 10 * time.Second

 // tickCmd returns a tick command for periodic refresh
 func tickCmd() tea.Cmd {
diff --git i/internal/ui/oci_resources/model.go w/internal/ui/oci_resources/model.go
index 35cb2784..c90d21f8 100644
--- i/internal/ui/oci_resources/model.go
+++ w/internal/ui/oci_resources/model.go
@@ -34,7 +34,10 @@ const (

 // Model represents the OCI resources view state
 type Model struct {
-	config    *config.Config
+	config *config.Config
+	// blurred is true while the terminal window has lost the focus
+	// (DEVDESK-210): the periodic refresh skips its reads.
+	blurred   bool
 	activeTab ociTab
 	// Images tab
 	images []docker.Image
diff --git i/internal/ui/oci_resources/update.go w/internal/ui/oci_resources/update.go
index 44982268..198c4234 100644
--- i/internal/ui/oci_resources/update.go
+++ w/internal/ui/oci_resources/update.go
@@ -28,6 +28,12 @@ func (m Model) Init() tea.Cmd {
 	)
 }

+// refreshReads lists images, networks and volumes and loads the scan cache.
+// It never scans (Rule 126).
+func (m Model) refreshReads() tea.Cmd {
+	return tea.Batch(fetchImages(), loadScanCache(), fetchNetworks(), fetchVolumes())
+}
+
 // Update handles messages
 func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 	switch msg := msg.(type) {
@@ -106,8 +112,21 @@ func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 			return m, tea.Batch(cmds...)
 		}

+	case shared.TerminalFocusMsg:
+		m.blurred = !msg.Focused
+		if !msg.Resume {
+			return m, nil
+		}
+		// One re-read on the focus edge, no new tick: the chain kept its timer.
+		return m, m.refreshReads()
+
 	case RefreshTickMsg:
-		return m, tea.Batch(fetchImages(), loadScanCache(), fetchNetworks(), fetchVolumes())
+		// The tick rearms itself (it used to run only once) and skips the
+		// reads while the terminal is blurred.
+		if m.blurred {
+			return m, tickCmd()
+		}
+		return m, tea.Batch(m.refreshReads(), tickCmd())

 	case ImagesListMsg:
 		return m.handleImagesList(msg)

