		{Focused: false, Resume: false},
		{Focused: true, Resume: false}, // entry level
	} {
		if _, cmd := m.Update(msg); cmd != nil {
			t.Errorf("%+v returned a Cmd, want nil (flag only)", msg)
		}
	}
}
