// refreshInterval is the cadence of the view's reload. A variable so a test can
// shorten it: tea.Tick sleeps for the whole duration.
var refreshInterval = 2 * time.Second

// tickCmd returns the next tick of the periodic refresh. It is a single shot:
// each RefreshTickMsg asks for the one after it, and the chain ends by itself
// when the view stops being the active one, because the router then hands the
// tick to the view on screen, which ignores it. Init starts a new chain on the
// way back in.
func tickCmd() tea.Cmd {
	return tea.Tick(refreshInterval, func(t time.Time) tea.Msg {
		return RefreshTickMsg(t)
	})
}

// fetchContainers fetches the container list — always all of it.
			// The load is reported in the footer, so the frame has to reach it —
			// a spinner stuck on frame zero reads as a hang.
			m.footer.SetSpinnerFrame(m.spinner.View())
			return m, cmd
		}

	case RefreshTickMsg:
		// The next tick is requested here: a tick that does not re-arm itself
		// refreshes once, two seconds after Init, and never again — which is
		// what made ctrl+r the only way to see the gauges move.
		return m, tea.Batch(tickCmd(), fetchContainers(), fetchMetrics())

	case ContainersListMsg:
		return m.handleContainersList(msg)

	case ContainerMetricsMsg:
		return m.handleContainerMetrics(msg)

	case ContainerUpdatesCheckedMsg:
		return m.handleContainerUpdatesChecked(msg)

	case ContainerActionMsg:
		return m.handleContainerAction(msg)
		if cmd != nil {
			cmds = append(cmds, cmd)
		}
	}

	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return tea.Batch(cmds...)
}

