// refreshAll runs the slow clock's work. It only rearms its own clock: the
// other two have theirs, and a slow round that restarted them would make two
// tick chains for the same clock, hence samples twice as fast.
func (m Model) refreshAll() tea.Cmd {
	return tea.Batch(m.slowRound(), m.scheduleRefresh())
}

// slowRound is the slow clock's reads, without its timer.
func (m Model) slowRound() tea.Cmd {
	return tea.Batch(
		m.checkServices(),
		m.fetchForgeStats(),
		m.fetchDockerStats(),
		m.fetchOCIStats(),
		m.fetchWorkspaceStats(),
		m.fetchDiskUsage(),
		m.fetchPosture(),
	)
}

// refreshNow is what ctrl+r does: the slow round plus one immediate reading
// from each of the other two clocks, **without rearming** their ticks.
func (m Model) refreshNow() tea.Cmd {
	return tea.Batch(
		m.refreshAll(),
		m.sampleHost(),
		m.fetchDockerMetrics(),
		requestToolsDetection(),
	)
}

